changeSet.sql:
ALTER TABLE core.asset_reference
ADD CONSTRAINT ck_asset_reference_asset_type
CHECK (asset_type IN ('attachment', 'image'));

ALTER TABLE core.asset_reference
ADD CONSTRAINT ck_asset_reference_source_kind
CHECK (source_kind IN ('draft_doc', 'published_doc', 'comment_reply'));

ALTER TABLE core.asset_reference_coverage
ADD CONSTRAINT ck_asset_reference_coverage_draft_status
CHECK (draft_status IN ('unknown', 'indexed', 'blocked_binary_draft'));
